with v(lesson_id, so, typ, pl) as (values
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 7' and l.title='Homework 1'), 7, 'exact_input', $blk${"title": "Напиши слово по-английски", "items": [{"prompt": "прибыть", "accept": ["arrive"], "audio_tts": "arrive"}, {"prompt": "сесть, войти (в автобус)", "accept": ["get on"], "audio_tts": "get on"}, {"prompt": "выйти (из поезда)", "accept": ["get off"], "audio_tts": "get off"}, {"prompt": "уезжать, отправляться", "accept": ["leave"], "audio_tts": "leave"}, {"prompt": "сесть на (транспорт), поехать на", "accept": ["take"], "audio_tts": "take"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 7' and l.title='Unit 7 Test'), 0, 'exact_input', $blk${"title": "VOCABULARY. Напиши слово по-английски — по картинке или по русскому слову", "items": [{"prompt": "прибыть", "accept": ["arrive"]}, {"prompt": "", "accept": ["boat", "a boat"], "image": "https://classroom.wowteach.ru/media/gg2/u7/boat.webp"}, {"prompt": "", "accept": ["motorbike", "a motorbike"], "image": "https://classroom.wowteach.ru/media/gg2/u7/motorbike.webp"}, {"prompt": "", "accept": ["plane", "a plane"], "image": "https://classroom.wowteach.ru/media/gg2/u7/plane.webp"}, {"prompt": "", "accept": ["train", "a train"], "image": "https://classroom.wowteach.ru/media/gg2/u7/train.webp"}, {"prompt": "", "accept": ["underground", "the underground"], "image": "https://classroom.wowteach.ru/media/gg2/u7/underground.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 8' and l.title='Homework 1'), 3, 'exact_input', $blk${"title": "Напиши слово по-английски — по картинке или по русскому слову", "items": [{"prompt": "", "accept": ["barbecue"], "image": "https://classroom.wowteach.ru/media/gg2/u8/barbecue.webp", "audio_tts": "barbecue"}, {"prompt": "", "accept": ["birthday party"], "image": "https://classroom.wowteach.ru/media/gg2/u8/birthday_party.webp", "audio_tts": "birthday party"}, {"prompt": "", "accept": ["concert"], "image": "https://classroom.wowteach.ru/media/gg2/u8/concert.webp", "audio_tts": "concert"}, {"prompt": "танцевальное шоу", "accept": ["dance show"], "image": "https://classroom.wowteach.ru/media/gg2/u8/dance_show.webp", "audio_tts": "dance show"}, {"prompt": "", "accept": ["football match"], "image": "https://classroom.wowteach.ru/media/gg2/u8/football_match.webp", "audio_tts": "football match"}, {"prompt": "костюмированная вечеринка", "accept": ["fancy dress party"], "image": "https://classroom.wowteach.ru/media/gg2/u8/fancy_dress.webp", "audio_tts": "fancy dress party"}, {"prompt": "", "accept": ["picnic"], "image": "https://classroom.wowteach.ru/media/gg2/u8/picnic.webp", "audio_tts": "picnic"}, {"prompt": "пьеса", "accept": ["play"], "image": "https://classroom.wowteach.ru/media/gg2/u8/play.webp", "audio_tts": "play"}, {"prompt": "", "accept": ["sleepover"], "image": "https://classroom.wowteach.ru/media/gg2/u8/sleepover.webp", "audio_tts": "sleepover"}, {"prompt": "", "accept": ["talent competition"], "image": "https://classroom.wowteach.ru/media/gg2/u8/talent_competition.webp", "audio_tts": "talent competition"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 8' and l.title='Unit 8 Test'), 0, 'exact_input', $blk${"title": "Напиши слово по-английски — по картинке или по русскому слову", "items": [{"prompt": "", "accept": ["barbecue"], "image": "https://classroom.wowteach.ru/media/gg2/u8/barbecue.webp"}, {"prompt": "танцевальное шоу", "accept": ["dance show"], "image": "https://classroom.wowteach.ru/media/gg2/u8/dance_show.webp"}, {"prompt": "костюмированная вечеринка", "accept": ["fancy dress party"], "image": "https://classroom.wowteach.ru/media/gg2/u8/fancy_dress.webp"}, {"prompt": "", "accept": ["picnic"], "image": "https://classroom.wowteach.ru/media/gg2/u8/picnic.webp"}, {"prompt": "", "accept": ["sleepover"], "image": "https://classroom.wowteach.ru/media/gg2/u8/sleepover.webp"}, {"prompt": "", "accept": ["talent competition"], "image": "https://classroom.wowteach.ru/media/gg2/u8/talent_competition.webp"}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Final Test' and l.title='Final Test'), 1, 'exact_input', $blk${"items": [{"prompt": "", "accept": ["wardrobe", "Wardrobe"], "image": "https://classroom.wowteach.ru/media/gg2/u0/wardrobe.webp"}, {"prompt": "словарь", "accept": ["dictionary", "Dictionary"]}, {"prompt": "", "accept": ["vegetables", "Vegetables"], "image": "https://classroom.wowteach.ru/media/gg2/u2/vegetables.webp"}, {"prompt": "", "accept": ["headphones", "Headphones"], "image": "https://classroom.wowteach.ru/media/gg2/u3/headphones.webp"}, {"prompt": "", "accept": ["waterfall", "Waterfall"], "image": "https://classroom.wowteach.ru/media/gg2/u4/waterfall.webp"}, {"prompt": "", "accept": ["museum", "Museum"], "image": "https://classroom.wowteach.ru/media/gg2/u5/museum.webp"}, {"prompt": "", "accept": ["builder", "Builder"], "image": "https://classroom.wowteach.ru/media/gg2/u6/builder.webp"}, {"prompt": "", "accept": ["suitcase", "Suitcase"], "image": "https://classroom.wowteach.ru/media/gg2/u7/suitcase.webp"}, {"prompt": "", "accept": ["sleepover", "Sleepover"], "image": "https://classroom.wowteach.ru/media/gg2/u8/sleepover.webp"}, {"prompt": "опасный", "accept": ["dangerous", "Dangerous"]}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Unit 6' and l.title='Homework 2'), 13, 'sort', $blk${"title": "Здорово! Ты так хорошо справляешься! Какие слова говорят о прошлом (Past Simple), а какие — о настоящем или будущем? Распредели их", "groups": [{"name": "Past · прошлое", "items": [{"text": "yesterday"}, {"text": "last week"}, {"text": "last year"}, {"text": "last Saturday"}, {"text": "two days ago"}, {"text": "an hour ago"}, {"text": "in 1999"}]}, {"name": "Now / Future · сейчас и будущее", "items": [{"text": "now"}, {"text": "today"}, {"text": "every day"}, {"text": "tomorrow"}, {"text": "next week"}]}]}$blk$),
  ((select l.id from classroom_lessons l join classroom_units u on u.id=l.unit_id join classroom_courses c on c.id=u.course_id
   where c.slug='gg2' and u.title='Final Test' and l.title='Final Test'), 0, 'text', $blk${"html": "<h3>DICTATION ✍️</h3><p>Посмотри на картинку и впиши слово по-английски. Где картинки нет — переведи русское слово.</p>"}$blk$)),
upd as (update classroom_blocks b set type=v.typ, payload=v.pl::jsonb from v where b.lesson_id=v.lesson_id and b.sort_order=v.so returning b.lesson_id)
select count(*) from upd;